import json
items=json.load(open('/tmp/w4items.json'))
par={k:(v['md'] or {}).get('parent') for k,v in items.items()}
st={k:v['status'] for k,v in items.items()}
kids={}
for k,p in par.items():
    if p: kids.setdefault(p,[]).append(k)
print("PARENT/CHILD DISAGREEMENTS under AJCR.w4-rep:")
for p,cs in sorted(kids.items()):
    ps=st.get(p)
    css={c:st[c] for c in cs}
    vals=set(css.values())
    notes=[]
    if ps=='done' and vals-{'done','rejected'}: notes.append('parent done but children not all done')
    if ps in ('pending',) and any(v in ('active','done') for v in css.values()): notes.append('parent pending, children active/done')
    if ps=='blocked' and any(v=='done' for v in css.values()): notes.append('parent blocked, some children done')
    if ps=='blocked' and all(v in ('done','rejected') for v in css.values()): notes.append('parent blocked, ALL children terminal')
    if notes:
        print(f"  {p} [{ps}] -> {notes}")
        for c,v in sorted(css.items()): print(f"      {v:9s} {c}")
